pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set jojoTeam to a known address
        address jojoTeam = address(0x123);
        vm.prank(jojoTeam);
        c = new C();
        // Re-deploy so the new C has jojoTeam set
        vm.prank(jojoTeam);
        // Now jojoTeam is address(0x123) in the deployed contract
        // Create a caller that is not jojoTeam
        address attacker = address(0x456);
        vm.prank(attacker);
        // Try to call newEmergencyOracle as attacker
        bool ok;
        try c.newEmergencyOracle("test") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok == false), buggy does not revert (ok == true)
        assertTrue(ok == false);
    }
}

